#ifndef GUARD_CONSTANTS_TASK_SKIP_H
#define GUARD_CONSTANTS_TASK_SKIP_H

/*
 * Task skip mask (#155 run 7, the owner's decision R3). Task.skipMask holds
 * one bit per phase of RunTasks (src/early_5228.c) that the task sits out:
 * its coroutine, its move, update and late-update callbacks and its draw;
 * TaskSetSkipMask and its siblings set it for the running task, the other
 * tasks or all of them. Generated by tools/constants.py; each define is
 * logged with its evidence in docs/analysis/constants.csv.
 */

/* Task skip flags - Task.skipMask, one bit per RunTasks phase (src/early_5228.c); TaskSetSkipMask / TaskSetOthersSkipMask / TaskSetAllSkipMask / TaskFreezeOrThawOthers store or OR them (src/early_55b0.c, src/early_6464.c) */
#define TASK_SKIP_COROUTINE    1    /* the coroutine is not resumed */
#define TASK_SKIP_MOVE         2    /* moveCallback is skipped */
#define TASK_SKIP_UPDATE       4    /* updateCallback is skipped */
#define TASK_SKIP_LATE_UPDATE  8    /* lateUpdateCallback is skipped */
#define TASK_SKIP_DRAW         0x10 /* drawCallback is skipped */

#endif // GUARD_CONSTANTS_TASK_SKIP_H
